"""Generate the bundled SYNTHETIC OHLCV CSV files in ``data/``.

The data is produced by a seeded geometric Brownian motion with slowly drifting
regimes. It is deterministic, contains no real market prices and exists only so the
service works offline out of the box.

Usage::

    python scripts/generate_synthetic_data.py [output_dir]
"""

from __future__ import annotations

import sys
from pathlib import Path

import numpy as np
import pandas as pd

HEADER = (
    "# SYNTHETIC DATA - generated by scripts/generate_synthetic_data.py.\n"
    "# Not real market prices. Do not use for trading decisions.\n"
)

#: symbol -> (start price, per-bar volatility at 1h, base volume, seed)
SYMBOLS: dict[str, tuple[float, float, float, int]] = {
    "BTCUSDT": (60_000.0, 0.006, 250.0, 101),
    "ETHUSDT": (3_000.0, 0.008, 1_800.0, 202),
    "SOLUSDT": (150.0, 0.011, 25_000.0, 303),
}

#: interval -> (bar count, pandas frequency, volatility multiplier, start timestamp)
INTERVALS: dict[str, tuple[int, str, float, str]] = {
    "1h": (1000, "1h", 1.0, "2025-01-01T00:00:00Z"),
    "1d": (400, "1D", 4.9, "2024-01-01T00:00:00Z"),
}


def generate(
    start_price: float, sigma: float, base_volume: float, bars: int, seed: int
) -> pd.DataFrame:
    """Return a synthetic OHLCV frame (without timestamps) of ``bars`` rows."""
    rng = np.random.default_rng(seed)
    # Regime drift: a smooth random walk so the series trends, ranges and reverses.
    drift = np.convolve(rng.normal(0, sigma * 0.15, bars), np.ones(48) / 48, mode="same")
    returns = drift + rng.normal(0, sigma, bars)
    close = start_price * np.exp(np.cumsum(returns))
    open_ = np.empty(bars)
    open_[0] = start_price
    open_[1:] = close[:-1] * (1 + rng.normal(0, sigma * 0.05, bars - 1))
    wick_up = np.abs(rng.normal(0, sigma * 0.6, bars))
    wick_down = np.abs(rng.normal(0, sigma * 0.6, bars))
    high = np.maximum(open_, close) * (1 + wick_up)
    low = np.minimum(open_, close) * (1 - wick_down)
    volume = base_volume * rng.lognormal(0, 0.45, bars) * (1 + 40 * np.abs(returns))
    decimals = 2 if start_price >= 100 else 4
    return pd.DataFrame(
        {
            "open": open_.round(decimals),
            "high": high.round(decimals),
            "low": low.round(decimals),
            "close": close.round(decimals),
            "volume": volume.round(3),
        }
    )


def main(out_dir: Path) -> None:
    """Write one CSV per (symbol, interval) into ``out_dir``."""
    out_dir.mkdir(parents=True, exist_ok=True)
    for symbol, (price, sigma, volume, seed) in SYMBOLS.items():
        for interval, (bars, freq, vol_mult, start) in INTERVALS.items():
            frame = generate(price, sigma * vol_mult, volume, bars, seed + bars)
            times = pd.date_range(start=start, periods=bars, freq=freq)
            frame.insert(0, "open_time", times.strftime("%Y-%m-%dT%H:%M:%SZ"))
            path = out_dir / f"{symbol}_{interval}.csv"
            with path.open("w", encoding="utf-8", newline="") as fh:
                fh.write(HEADER)
                frame.to_csv(fh, index=False)
            print(f"wrote {path} ({bars} rows)")


if __name__ == "__main__":
    main(Path(sys.argv[1]) if len(sys.argv) > 1 else Path(__file__).resolve().parents[1] / "data")
